/// Return metadata for every CAN message in the DBC.
pub const fn get_all_mess() -> &'static [MessageInfo] { ALL_MESSAGES }

pub fn get_message(id: u32) -> Option<&'static MessageInfo> {
    ALL_MESSAGES.iter().find(|message| message.id == id)
}

pub fn get_all_signals(id: u32) -> Option<&'static [SignalInfo]> {
    get_message(id).map(|message| message.signals)
}

pub fn get_signal(id: u32, name: &str) -> Option<&'static SignalInfo> {
    get_all_signals(id)?.iter().find(|signal| signal.name == name)
}

pub fn message_dlc(id: u32) -> Option<u8> { get_message(id).map(|m| m.dlc) }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Message {
    MatrixIntelTypes(MatrixIntelTypes),
    MatrixIntelScaled(MatrixIntelScaled),
    MatrixMotorolaTypes(MatrixMotorolaTypes),
    MatrixMotorolaScaled(MatrixMotorolaScaled),
    MatrixFloat(MatrixFloat),
    MatrixDouble(MatrixDouble),
    MatrixWideScaled(MatrixWideScaled),
    MatrixCollision(MatrixCollision),
}

impl Message {
    pub const fn id(&self) -> u32 {
        match self {
            Self::MatrixIntelTypes(_) => MatrixIntelTypes::ID,
            Self::MatrixIntelScaled(_) => MatrixIntelScaled::ID,
            Self::MatrixMotorolaTypes(_) => MatrixMotorolaTypes::ID,
            Self::MatrixMotorolaScaled(_) => MatrixMotorolaScaled::ID,
            Self::MatrixFloat(_) => MatrixFloat::ID,
            Self::MatrixDouble(_) => MatrixDouble::ID,
            Self::MatrixWideScaled(_) => MatrixWideScaled::ID,
            Self::MatrixCollision(_) => MatrixCollision::ID,
        }
    }

    pub const fn dlc(&self) -> u8 {
        match self {
            Self::MatrixIntelTypes(_) => MatrixIntelTypes::DLC,
            Self::MatrixIntelScaled(_) => MatrixIntelScaled::DLC,
            Self::MatrixMotorolaTypes(_) => MatrixMotorolaTypes::DLC,
            Self::MatrixMotorolaScaled(_) => MatrixMotorolaScaled::DLC,
            Self::MatrixFloat(_) => MatrixFloat::DLC,
            Self::MatrixDouble(_) => MatrixDouble::DLC,
            Self::MatrixWideScaled(_) => MatrixWideScaled::DLC,
            Self::MatrixCollision(_) => MatrixCollision::DLC,
        }
    }

    pub const fn payload(&self) -> u64 {
        match self {
            Self::MatrixIntelTypes(message) => message.payload(),
            Self::MatrixIntelScaled(message) => message.payload(),
            Self::MatrixMotorolaTypes(message) => message.payload(),
            Self::MatrixMotorolaScaled(message) => message.payload(),
            Self::MatrixFloat(message) => message.payload(),
            Self::MatrixDouble(message) => message.payload(),
            Self::MatrixWideScaled(message) => message.payload(),
            Self::MatrixCollision(message) => message.payload(),
        }
    }

    pub const fn frame(&self) -> CanFrame {
        CanFrame { id: self.id(), dlc: self.dlc(), payload: self.payload() }
    }

    pub const fn get_matrixinteltypes(&self) -> Option<&MatrixIntelTypes> {
        match self { Self::MatrixIntelTypes(message) => Some(message), _ => None }
    }

    pub fn get_matrixinteltypes_mut(&mut self) -> Option<&mut MatrixIntelTypes> {
        match self { Self::MatrixIntelTypes(message) => Some(message), _ => None }
    }

    pub const fn get_matrixintelscaled(&self) -> Option<&MatrixIntelScaled> {
        match self { Self::MatrixIntelScaled(message) => Some(message), _ => None }
    }

    pub fn get_matrixintelscaled_mut(&mut self) -> Option<&mut MatrixIntelScaled> {
        match self { Self::MatrixIntelScaled(message) => Some(message), _ => None }
    }

    pub const fn get_matrixmotorolatypes(&self) -> Option<&MatrixMotorolaTypes> {
        match self { Self::MatrixMotorolaTypes(message) => Some(message), _ => None }
    }

    pub fn get_matrixmotorolatypes_mut(&mut self) -> Option<&mut MatrixMotorolaTypes> {
        match self { Self::MatrixMotorolaTypes(message) => Some(message), _ => None }
    }

    pub const fn get_matrixmotorolascaled(&self) -> Option<&MatrixMotorolaScaled> {
        match self { Self::MatrixMotorolaScaled(message) => Some(message), _ => None }
    }

    pub fn get_matrixmotorolascaled_mut(&mut self) -> Option<&mut MatrixMotorolaScaled> {
        match self { Self::MatrixMotorolaScaled(message) => Some(message), _ => None }
    }

    pub const fn get_matrixfloat(&self) -> Option<&MatrixFloat> {
        match self { Self::MatrixFloat(message) => Some(message), _ => None }
    }

    pub fn get_matrixfloat_mut(&mut self) -> Option<&mut MatrixFloat> {
        match self { Self::MatrixFloat(message) => Some(message), _ => None }
    }

    pub const fn get_matrixdouble(&self) -> Option<&MatrixDouble> {
        match self { Self::MatrixDouble(message) => Some(message), _ => None }
    }

    pub fn get_matrixdouble_mut(&mut self) -> Option<&mut MatrixDouble> {
        match self { Self::MatrixDouble(message) => Some(message), _ => None }
    }

    pub const fn get_matrixwidescaled(&self) -> Option<&MatrixWideScaled> {
        match self { Self::MatrixWideScaled(message) => Some(message), _ => None }
    }

    pub fn get_matrixwidescaled_mut(&mut self) -> Option<&mut MatrixWideScaled> {
        match self { Self::MatrixWideScaled(message) => Some(message), _ => None }
    }

    pub const fn get_matrixcollision(&self) -> Option<&MatrixCollision> {
        match self { Self::MatrixCollision(message) => Some(message), _ => None }
    }

    pub fn get_matrixcollision_mut(&mut self) -> Option<&mut MatrixCollision> {
        match self { Self::MatrixCollision(message) => Some(message), _ => None }
    }

}

pub fn decode_message(id: u32, payload: u64, dlc: u8) -> Result<Message, DbccError> {
    match id {
        CAN_ID_MATRIXINTELTYPES => {
            if dlc != CAN_DLC_MATRIXINTELTYPES {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXINTELTYPES, actual: dlc });
            }
            Ok(Message::MatrixIntelTypes(MatrixIntelTypes::from_payload(payload)))
        }
        CAN_ID_MATRIXINTELSCALED => {
            if dlc != CAN_DLC_MATRIXINTELSCALED {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXINTELSCALED, actual: dlc });
            }
            Ok(Message::MatrixIntelScaled(MatrixIntelScaled::from_payload(payload)))
        }
        CAN_ID_MATRIXMOTOROLATYPES => {
            if dlc != CAN_DLC_MATRIXMOTOROLATYPES {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXMOTOROLATYPES, actual: dlc });
            }
            Ok(Message::MatrixMotorolaTypes(MatrixMotorolaTypes::from_payload(payload)))
        }
        CAN_ID_MATRIXMOTOROLASCALED => {
            if dlc != CAN_DLC_MATRIXMOTOROLASCALED {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXMOTOROLASCALED, actual: dlc });
            }
            Ok(Message::MatrixMotorolaScaled(MatrixMotorolaScaled::from_payload(payload)))
        }
        CAN_ID_MATRIXFLOAT => {
            if dlc != CAN_DLC_MATRIXFLOAT {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXFLOAT, actual: dlc });
            }
            Ok(Message::MatrixFloat(MatrixFloat::from_payload(payload)))
        }
        CAN_ID_MATRIXDOUBLE => {
            if dlc != CAN_DLC_MATRIXDOUBLE {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXDOUBLE, actual: dlc });
            }
            Ok(Message::MatrixDouble(MatrixDouble::from_payload(payload)))
        }
        CAN_ID_MATRIXWIDESCALED => {
            if dlc != CAN_DLC_MATRIXWIDESCALED {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXWIDESCALED, actual: dlc });
            }
            Ok(Message::MatrixWideScaled(MatrixWideScaled::from_payload(payload)))
        }
        CAN_ID_MATRIXCOLLISION => {
            if dlc != CAN_DLC_MATRIXCOLLISION {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_MATRIXCOLLISION, actual: dlc });
            }
            Ok(Message::MatrixCollision(MatrixCollision::from_payload(payload)))
        }
        _ => Err(DbccError::UnknownMessage { id }),
    }
}

